{
  "arguments": [
    {
      "claim": "The killings and serious bodily or mental harm inflicted on Croats satisfy the actus reus elements of genocide under Articles 2(a) and 2(b) of the Genocide Convention.",
      "reasoning": "The factual record shows that Croat civilians were deliberately killed in Vukovar, Ovčara, Bogdanovci, Lovas, Dalj, Škabrnja and Nadin, and were subjected to torture, sexual violence and other serious injuries. These conduct elements correspond precisely to the enumerated acts of \"Killing members of the group\" and \"Causing serious bodily or mental harm to members of the group\" in the Convention.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "genocide",
          "article": "art.2(a)",
          "quoted_text": "Killing members of the group;"
        },
        {
          "type": "treaty",
          "instrument": "genocide",
          "article": "art.2(b)",
          "quoted_text": "Causing serious bodily or mental harm to members of the group;"
        }
      ]
    },
    {
      "claim": "The perpetrators acted with the specific intent to destroy, in whole or in part, the Croat ethnic group, satisfying the mens rea element of genocide.",
      "reasoning": "The systematic pattern of attacks on civilian Croat localities, the documented aim of creating an ethnically homogeneous Serb State, and the ICTY’s finding of a shared leadership goal demonstrate that the actors intended to eliminate the Croat group as such. Under Article 2 of the Genocide Convention and Article 6 of the Rome Statute, genocide requires the specific intent to destroy a national, ethnical, racial or religious group, which is satisfied here.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "genocide",
          "article": "art.2",
          "quoted_text": "In the present Convention, genocide means any of the following acts committed with intent to destroy, in whole or in part, a national, ethnical, racial or religious group, as such:"
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "art.6",
          "quoted_text": "For the purpose of this Statute, \"genocide\" means any of the following acts committed with intent to destroy, in whole or in part, a national, ethnical, racial or religious group, as such:"
        }
      ]
    },
    {
      "claim": "The attacks were directed at a substantial part of the Croat population, meeting the \"in whole or in part\" requirement of the genocide definition.",
      "reasoning": "The six regions targeted contained between 1.7 and 1.8 million Croats—approximately half of Croatia’s Croat population. The scale of killings (about 12,500 deaths) and forced displacement (80,000‑100,000 persons) indicates that a substantial part of the group was the object of the campaign. The Convention’s wording \"in whole or in part\" expressly covers the destruction of a substantial part of a protected group.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "genocide",
          "article": "art.2",
          "quoted_text": "In the present Convention, genocide means any of the following acts committed with intent to destroy, in whole or in part, a national, ethnical, racial or religious group, as such:"
        }
      ]
    },
    {
      "claim": "Although the conduct also constitutes war crimes, the proven specific intent to destroy the Croat group elevates the crimes to genocide rather than merely war crimes.",
      "reasoning": "War crimes under Article 8 of the Rome Statute, such as \"Wilful killing,\" require a breach of the laws of armed conflict but do not require the specific intent to eradicate a protected group. The presence of the dolus specialis to destroy Croats, as established in arguments 2 and 3, satisfies the higher threshold of genocide. Consequently, the acts are not limited to war crimes but constitute genocide.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "art.8",
          "quoted_text": "Wilful killing;"
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "art.6",
          "quoted_text": "For the purpose of this Statute, \"genocide\" means any of the following acts committed with intent to destroy, in whole or in part, a national, ethnical, racial or religious group, as such:"
        }
      ]
    }
  ]
}

