{
  "arguments": [
    {
      "claim": "The killings and serious bodily or mental harm inflicted on Croats satisfy the actus reus element of genocide.",
      "reasoning": "Genocide is defined by the Convention as including the acts of killing members of a protected group and causing serious bodily or mental harm to them. The factual record shows intentional attacks on Croat civilians in Vukovar, Ovčara, Bogdanovci, Lovas, Dalj, Škabrnja, Nadin and other localities. Under the Rome Statute, such conduct is captured by the provision that prohibits intentionally directing attacks against the civilian population. Accordingly, the conduct meets the enumerated acts required for the physical element of genocide.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "genocide",
          "article": "2(a)",
          "quoted_text": "Killing members of the group;"
        },
        {
          "type": "treaty",
          "instrument": "genocide",
          "article": "2(b)",
          "quoted_text": "Causing serious bodily or mental harm to members of the group;"
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Intentionally directing attacks against the civilian population as such or against individual civilians not taking direct part in hostilities;"
        }
      ]
    },
    {
      "claim": "The perpetrators acted with the specific intent (dolus specialis) to destroy the Croat ethnic group, at least in part.",
      "reasoning": "The Convention requires that genocide be committed with intent to destroy the group \"as such.\" The systematic pattern of attacks on Croat‑populated areas, coupled with the documented objective of creating an ethnically homogeneous Serb State, demonstrates that the actors intended to eliminate the Croat presence, not merely to achieve a military or territorial goal. This specific intent is precisely the mens rea required by both the Genocide Convention and the Rome Statute. Moreover, the existence of a coordinated plan or policy is reflected in the Statute’s provision on war crimes committed as part of a plan or policy, confirming the organized nature of the conduct.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "genocide",
          "article": "2",
          "quoted_text": "In the present Convention, genocide means any of the following acts committed with intent to destroy, in whole or in part, a national, ethnical, racial or religious group, as such:"
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "6",
          "quoted_text": "For the purpose of this Statute, \"genocide\" means any of the following acts committed with intent to destroy, in whole or in part, a national, ethnical, racial or religious group, as such:"
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "The Court shall have jurisdiction in respect of war crimes in particular when committed as part of a plan or policy or as part of a large-scale commission of such crimes."
        }
      ]
    },
    {
      "claim": "The Croat population targeted constitutes a substantial part of the group, satisfying the \"in whole or in part\" requirement of the genocide definition.",
      "reasoning": "The six regions affected contained between 1.7 and 1.8 million Croats, roughly half of Croatia’s Croat population. The campaign resulted in approximately 12,500 deaths and the forced displacement of 80,000‑100,000 persons, representing a significant portion of that regional population. The Convention’s wording \"in whole or in part\" does not prescribe a fixed percentage; jurisprudence interprets a \"substantial part\" as a portion whose destruction would materially affect the group’s existence. The scale and geographic concentration of the attacks meet this standard.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "genocide",
          "article": "2",
          "quoted_text": "In the present Convention, genocide means any of the following acts committed with intent to destroy, in whole or in part, a national, ethnical, racial or religious group, as such:"
        }
      ]
    },
    {
      "claim": "Because both the actus reus and the specific intent are established, the conduct constitutes genocide rather than merely war crimes.",
      "reasoning": "War crimes under the Rome Statute require a breach of the laws of armed conflict but do not require the special intent to destroy a protected group. The proven specific intent (dolus specialis) combined with the enumerated acts of killing and causing serious harm fulfills the higher threshold set by the Genocide Convention and the Rome Statute’s definition of genocide. Consequently, the acts must be characterized as genocide, not simply as war crimes.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "6",
          "quoted_text": "For the purpose of this Statute, \"genocide\" means any of the following acts committed with intent to destroy, in whole or in part, a national, ethnical, racial or religious group, as such:"
        },
        {
          "type": "treaty",
          "instrument": "genocide",
          "article": "2",
          "quoted_text": "In the present Convention, genocide means any of the following acts committed with intent to destroy, in whole or in part, a national, ethnical, racial or religious group, as such:"
        }
      ]
    }
  ]
}

